Here's my rule for whether a worktree can be deleted:

func CanDelete(wt Worktree) error {
    cfg, _ := config.Load()
    if slices.Contains(cfg.Protected, wt.Branch) { return errors.New("protected") }
    out, _ := exec.Command("git", "-C", wt.Path, "status", "--porcelain").Output()
    if len(out) > 0 { return errors.New("dirty") }
    return nil
}

